function nonzeroTimesSum(n: number): number {
  const kept = String(n).split("").filter(c => c !== "0");
  if (kept.length === 0) return 0;
  const x = Number(kept.join(""));
  const sum = kept.reduce((s, c) => s + Number(c), 0);
  return x * sum;
}

