function nonzeroTimesSum(n: number): number {
  let x = 0, sum = 0, place = 1;
  while (n > 0) {
    const d = n % 10;
    n = Math.floor(n / 10);
    if (d !== 0) {
      x += d * place;
      sum += d;
      place *= 10;
    }
  }
  return x * sum;
}

